"use client";

import {
  createContext,
  useContext,
  useState,
  ReactNode,
} from "react";

type Book = {
  id: number;
  title: string;
  author: string;
  image: string;
};

type CartContextType = {
  cart: Book[];
  addToCart: (book: Book) => void;
  removeFromCart: (id: number) => void;
  clearCart: () => void;
};


const CartContext =
  createContext<CartContextType | null>(null);


export function CartProvider({
  children,
}: {
  children: ReactNode;
}) {

  const [cart, setCart] = useState<Book[]>([]);


  function addToCart(book: Book) {

    const alreadyExists =
      cart.some(
        (item) => item.id === book.id
      );


    if (alreadyExists) {
      return;
    }


    setCart((current) => [
      ...current,
      book,
    ]);

  }


  function removeFromCart(id: number) {

    setCart((current) =>
      current.filter(
        (book) => book.id !== id
      )
    );

  }


  function clearCart() {
    setCart([]);
  }


  return (

    <CartContext.Provider
      value={{
        cart,
        addToCart,
        removeFromCart,
        clearCart,
      }}
    >

      {children}

    </CartContext.Provider>

  );

}


export function useCart() {

  const context =
    useContext(CartContext);


  if (!context) {

    throw new Error(
      "useCart must be used inside CartProvider"
    );

  }


  return context;

}